    ("pii.phone",    r"\b(?:0\d{3}[\s-]?\d{3}[\s-]?\d{4}|0\d{4}[\s-]?\d{6}|\+44\s?\d{9,10})\b"),
    ("pii.postcode", r"\b[A-Z]{1,2}\d{1,2}[A-Z]?\s*\d[A-Z]{2}\b"),
